#include <stdio.h>
#include <string.h>

int main(void) {
    const char* txt = "GEEKS FOR GEEKS";
    const char* pat = "GEEK";
    int q = 101, d = 256;
    int n = (int)strlen(txt), m = (int)strlen(pat);
    int p = 0, t = 0, h = 1;

    for (int i = 0; i < m - 1; i++) h = (h * d) % q;
    for (int i = 0; i < m; i++) {
        p = (d * p + pat[i]) % q;
        t = (d * t + txt[i]) % q;
    }

    for (int i = 0; i <= n - m; i++) {
        if (p == t) {
            int match = 1;
            for (int j = 0; j < m; j++) {
                if (txt[i + j] != pat[j]) { match = 0; break; }
            }
            if (match) printf("Pattern found at index %d\n", i);
        }
        if (i < n - m) {
            t = (d * (t - txt[i] * h) + txt[i + m]) % q;
            if (t < 0) t += q;
        }
    }
    return 0;
}

